#include <stdio.h>
#include <stdlib.h>

int *parent, *sz;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int unite(int a, int b) {
    a = find(a);
    b = find(b);
    if (a == b) return 0;
    if (sz[a] < sz[b]) {
        int tmp = a;
        a = b;
        b = tmp;
    }
    parent[b] = a;
    sz[a] += sz[b];
    return 1;
}

int main() {
    int N, M, K;
    if (scanf("%d %d %d", &N, &M, &K) != 3) return 0;

    parent = (int *)malloc((N + 1) * sizeof(int));
    sz = (int *)malloc((N + 1) * sizeof(int));

    for (int i = 1; i <= N; i++) {
        parent[i] = i;
        sz[i] = 1;
    }

    int *ru = (int *)malloc((M + 1) * sizeof(int));
    int *rv = (int *)malloc((M + 1) * sizeof(int));
    int road_count = 0;
    int water_cycle = 0;

    for (int i = 0; i < M; i++) {
        int a, b, t;
        scanf("%d %d %d", &a, &b, &t);

        if (t == 1) {
            if (!unite(a, b)) {
                water_cycle = 1;
            }
        } else {
            ru[road_count] = a;
            rv[road_count] = b;
            road_count++;
        }
    }

    if (water_cycle) {
        printf("N\n");
        return 0;
    }

    int kept_roads = 0;

    for (int i = 0; i < road_count; i++) {
        if (unite(ru[i], rv[i])) {
            kept_roads++;
        }
    }

    int removed = road_count - kept_roads;

    if (removed <= K) {
        printf("S\n");
    } else {
        printf("N\n");
    }

    free(parent);
    free(sz);
    free(ru);
    free(rv);

    return 0;
}
